        + (who.length ? `Characters in this picture: ${whoDesc(who)}. ${['', 'Only one character', 'Only two characters', 'Only three characters', 'Only four characters', 'Exactly five characters', 'Exactly six characters', 'Exactly seven characters', 'Exactly eight characters'][who.length]} in the whole picture, each appearing once.${who.length > 4 ? ' The reference sheet shows them in this order, left to right, top row first.' : ''} Use the reference images only for each character's look and colors; draw new poses, expressions and positions that act out the sentence.` : 'Only show what the sentence mentions.')
        + ` Background: ${place}, drawn in the same style as the characters, everything illustrated, not a photo, not realistic.${note && who.some(c => new RegExp(note[0]).test(c[1])) ? ` ${note[1]}` : ''}`;
