const GROUP_PY = 'import sys\nfrom PIL import Image\nims=[Image.open(p).convert("RGB") for p in sys.argv[2:]]\nH=384\nims=[i.resize((max(1,i.width*H//i.height),H)) for i in ims]\ncols=4\nW=max(i.width for i in ims)\nrows=(len(ims)+cols-1)//cols\nc=Image.new("RGB",(W*cols,H*rows),"white")\nfor k,i in enumerate(ims):\n  c.paste(i,((k%cols)*W,(k//cols)*H))\nc.save(sys.argv[1])';
// 꾸미기 스티커: 가장자리에서 이어진 흰 배경을 지우고(hole이면 목도리 고리·안경알처럼 갇힌 큰 흰 칸도) 그림 크기에 맞게 잘라 PNG로 둔다
const CUT_PY = "import sys\nfrom PIL import Image, ImageDraw, ImageFilter\nf, mode = sys.argv[1], sys.argv[2]\nim = Image.open(f).convert(\"RGB\"); w, h = im.size; K, T, S = (255, 0, 255), (0, 255, 1), (0, 254, 0)\nm = im.copy()\nfor p in [(x, y) for x in range(0, w, 6) for y in (0, h - 1)] + [(x, y) for y in range(0, h, 6) for x in (0, w - 1)]:\n  c = m.getpixel(p)\n  if c != K and min(c) > 200: ImageDraw.floodfill(m, p, K, thresh=40)\nfor p in [(x, y) for x in range(0, w, 4) for y in range(0, h, 4)] if mode == \"hole\" else []:\n  c = m.getpixel(p)\n  if c in (K, S) or min(c) <= 228: continue\n  ImageDraw.floodfill(m, p, T, thresh=30)\n  n = m.getcolors(w * h) and dict((c, k) for k, c in m.getcolors(w * h)).get(T, 0)\n  ImageDraw.floodfill(m, p, K if n > w * h // 150 else S, thresh=0)\na = Image.new(\"L\", (w, h), 255); ap = a.load(); mp = m.load()\nfor y in range(h):\n  for x in range(w):\n    if mp[x, y] == K: ap[x, y] = 0\na = a.filter(ImageFilter.MinFilter(3)).filter(ImageFilter.GaussianBlur(0.8))\nim.putalpha(a); b = a.point(lambda v: 255 if v > 40 else 0).getbbox()\nif b: im = im.crop((max(0, b[0] - 3), max(0, b[1] - 3), min(w, b[2] + 3), min(h, b[3] + 3)))\nim.thumbnail((200, 200)); im.save(f, optimize=True)";
